def getLargestOutlier(nums):
    from collections import Counter
    freq = Counter(nums)
    total = sum(nums)
    best = None
    for x in nums:
        freq[x] -= 1
        s = total - x
        if s % 2 == 0:
            y = s // 2
            if freq.get(y, 0) > 0:
                if best is None or x > best:
                    best = x
        freq[x] += 1
    return best

