def minOperations(nums):
    def spf(x):
        if x <= 1:
            return None
        i = 2
        while i*i <= x:
            if x % i == 0:
                return i
            i += 1
        return None
    n = len(nums)
    limit = float("inf")
    ops = 0
    for i in range(n-1, -1, -1):
        x = nums[i]
        if x <= limit:
            limit = x
            continue
        p = spf(x)
        if p is not None and p <= limit:
            ops += 1
            limit = p
        else:
            return -1
    return ops

