def lengthAfterTransformations(s, t):
    MOD = 10**9 + 7
    cnt = [0]*26
    for ch in s:
        d = ord("z") - ord(ch)
        cnt[d] += 1
    for _ in range(t):
        new_cnt = [0]*26
        for d in range(26):
            c = cnt[d]
            if not c:
                continue
            if d == 0:
                new_cnt[25] = (new_cnt[25] + c) % MOD
                new_cnt[24] = (new_cnt[24] + c) % MOD
            else:
                new_cnt[d-1] = (new_cnt[d-1] + c) % MOD
        cnt = new_cnt
    return sum(cnt) % MOD

