def maxSubarraySum(nums, k):
    n = len(nums)
    P = [0]*(n+1)
    for i in range(n):
        P[i+1] = P[i] + nums[i]
    INF = float("inf")
    min_by_mod = [INF]*k
    best = -INF
    for r in range(n+1):
        m = r % k
        if min_by_mod[m] != INF:
            best = max(best, P[r] - min_by_mod[m])
        if P[r] < min_by_mod[m]:
            min_by_mod[m] = P[r]
    return best

