def minCost(n, cost):
    INF = float("inf")
    half = n // 2
    dp = {}
    for c0 in range(3):
        for c1 in range(3):
            if c0 == c1:
                continue
            dp[(c0, c1)] = cost[0][c0] + cost[n-1][c1]
    for i in range(1, half):
        j = n - 1 - i
        ndp = {}
        for c0 in range(3):
            for c1 in range(3):
                if c0 == c1:
                    continue
                best = INF
                for pc0 in range(3):
                    if pc0 == c0:
                        continue
                    for pc1 in range(3):
                        if pc1 == c1 or pc1 == pc0:
                            continue
                        key = (pc0, pc1)
                        if key in dp and dp[key] < best:
                            best = dp[key]
                if best < INF:
                    ndp[(c0, c1)] = best + cost[i][c0] + cost[j][c1]
        dp = ndp
    return min(dp.values())

