def maxSubstringLength(s, k):
    n = len(s)
    if k == 0:
        return True
    first = {}
    last = {}
    for i, c in enumerate(s):
        if c not in first:
            first[c] = i
        last[c] = i
    intervals = []
    for l in range(n):
        for r in range(l, n):
            if l == 0 and r == n - 1:
                continue
            chars = set(s[l:r+1])
            ok = True
            for c in chars:
                if first[c] < l or last[c] > r:
                    ok = False
                    break
            if ok:
                intervals.append((r, l))
    intervals.sort()
    count = 0
    last_end = -1
    for r, l in intervals:
        if l > last_end:
            count += 1
            last_end = r
    return count >= k

