def longestPalindrome(s, t):
    def substrs(u):
        n = len(u)
        out = []
        for i in range(n + 1):
            for j in range(i, n + 1):
                out.append(u[i:j])
        return out
    subs_s = substrs(s)
    subs_t = substrs(t)
    best = 0
    for a in subs_s:
        for b in subs_t:
            c = a + b
            if c == c[::-1] and len(c) > best:
                best = len(c)
    return best

