def maxActiveSectionsAfterTrade(s):
    t = "1" + s + "1"
    n = len(t)
    def mid_count(u):
        return u[1:-1].count("1")
    best = mid_count(t)
    i = 1
    while i < n - 1:
        if t[i] == "1":
            j = i
            while j + 1 < n - 1 and t[j+1] == "1":
                j += 1
            if t[i-1] == "0" and t[j+1] == "0":
                zt = t[:i] + "0"*(j-i+1) + t[j+1:]
                cand = mid_count(zt)
                best = max(best, cand)
                p = 0
                while p < n:
                    if zt[p] == "0":
                        q = p
                        while q + 1 < n and zt[q+1] == "0":
                            q += 1
                        if p - 1 >= 0 and zt[p-1] == "1" and q + 1 < n and zt[q+1] == "1":
                            ct = zt[:p] + "1"*(q-p+1) + zt[q+1:]
                            best = max(best, mid_count(ct))
                        p = q + 1
                    else:
                        p += 1
            i = j + 1
        else:
            i += 1
    return best

